        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    if num == 0:
        return (1, 0)

    # Handle negative numbers by taking the absolute value
    num = abs(num)

    even = 0
    odd = 0

    while num > 0:
        digit = num % 10
        if digit % 2 == 0:
            even += 1
        else:
            odd += 1
        num = num // 10

    return (even, odd)

