def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    if a < 2:
        return False

    factors = []
    for i in range(2, a + 1):
        if a % i == 0:
            factors.append(i)
            while a % i == 0:
                a = a // i
    factors.sort()

    prime_factors = []
    for factor in factors:
        if is_prime(factor):
            prime_factors.append(factor)

