        else:
            result += c
    return result

def encrypt(s):
    result = []
    for c in s:
        if c.isalpha():
            base = ord('a') if c.islower() else ord('A')
            result.append(chr((ord(c) - base + 4) % 26 + base))
        else:
            result.append(c)
    return ''.join(result)

