    if len(lst) <= 1:
        return True

    count = {}

    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False
        if lst[i] in count:
            count[lst[i]] += 1
        else:
            count[lst[i]] = 1

    # Check the last element
    if lst[-1] in count:
        count[lst[-1]] += 1
    else:
        count[lst[-1]] = 1

    for value in count.values():
        if value > 2:
            return False

    return True
