    if len(word) < 3:
        return ""

    vowels = "aeiouAEIOU"

    # Start from the third character from the right (index -3) and go left
    for i in range(len(word) - 3, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if both adjacent characters are consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""
