        # Try moving to all adjacent cells
        for di, dj in directions:
            ni, nj = i + di, j + dj
            # Check if the new position is within the grid bounds
            if 0 <= ni < N and 0 <= nj < N:
                path.append(grid[ni][nj])
                all_paths.extend(dfs(ni, nj, path, remaining_steps - 1))
                path.pop()  # Backtrack

